INSERT INTO `Course` (`course_ID`,`dept_ID`,`course_Name`,`course_Credits`,`course_DSC`,`course_Type`) VALUES
('ART10101','10','Introduction to Digital Media','4','Study of introduction to digital media, including foundational concepts, practical applications, and analysis of relevant problems.','Undergraduate'),
